CREATE TABLE public.application_telemetry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation text NOT NULL CHECK (operation IN ('assistant','recommendation','request')), outcome text NOT NULL CHECK (outcome IN ('success','failure')), duration_ms integer NOT NULL CHECK (duration_ms BETWEEN 0 AND 300000), code text NOT NULL DEFAULT 'none' CHECK (code IN ('none','provider','storage','receipt','internal')), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.application_telemetry TO service_role;
ALTER TABLE public.application_telemetry ENABLE ROW LEVEL SECURITY;
CREATE INDEX application_telemetry_created_idx ON public.application_telemetry(created_at DESC);
CREATE TABLE public.settings_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section text NOT NULL, source text NOT NULL, actor_id uuid, actor_label text NOT NULL DEFAULT '', previous_value jsonb NOT NULL, new_value jsonb NOT NULL, restored_from uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.settings_versions TO authenticated;
GRANT ALL ON public.settings_versions TO service_role;
ALTER TABLE public.settings_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_versions_admin_read ON public.settings_versions FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE INDEX settings_versions_section_idx ON public.settings_versions(section,created_at DESC);
CREATE TABLE public.retention_policies (data_type text PRIMARY KEY CHECK (data_type IN ('chats','visits','telemetry')), days integer NOT NULL CHECK (days BETWEEN 30 AND 730), manual_enabled boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT ON public.retention_policies TO authenticated;
GRANT ALL ON public.retention_policies TO service_role;
ALTER TABLE public.retention_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY retention_policies_admin_read ON public.retention_policies FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.settings_safe_value(v jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE result jsonb; k text; x jsonb; s text; BEGIN IF jsonb_typeof(v)='object' THEN result='{}'::jsonb; FOR k,x IN SELECT * FROM jsonb_each(v) LOOP IF k !~* '(key|secret|token|password|authorization|cookie)' THEN result=result||jsonb_build_object(k,public.settings_safe_value(x)); END IF; END LOOP; RETURN result; ELSIF jsonb_typeof(v)='array' THEN SELECT coalesce(jsonb_agg(public.settings_safe_value(value)),'[]'::jsonb) INTO result FROM jsonb_array_elements(v); RETURN result; ELSIF jsonb_typeof(v)='string' THEN s=v#>>'{}'; s=regexp_replace(s,'(https://[^[:space:]?]+)\?[^[:space:]]+','\1','g'); s=regexp_replace(s,'(sk-[a-zA-Z0-9_-]{12,}|gsk_[a-zA-Z0-9_-]{12,}|eyJ[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+)','[redacted]','g'); RETURN to_jsonb(s); END IF; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.settings_section_value(source_name text, section_name text, row_value jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE keys text[]; result jsonb; BEGIN IF source_name='site_settings' THEN keys=CASE section_name WHEN 'general' THEN ARRAY['display_title','display_title_en','arabic_title','tagline','tagline_en','description','description_en','footer_text','footer_text_en','footer_links','logo_url'] WHEN 'appearance' THEN ARRAY['heading_font','body_font','colors','design_theme','image_fit','image_brightness','image_contrast','image_saturation','image_sharpen','motion_enabled','motion_speed','motion_direction'] WHEN 'navigation' THEN ARRAY['navigation_items','nav_style','mobile_nav_style'] WHEN 'features' THEN ARRAY['feature_flags'] WHEN 'contact_info' THEN ARRAY['contact_info'] WHEN 'categories' THEN ARRAY['categories','categories_en'] WHEN 'customize' THEN ARRAY['theme_customizations'] WHEN 'terms' THEN ARRAY['terms_content'] WHEN 'archy' THEN ARRAY['archy_greeting'] ELSE ARRAY[]::text[] END; ELSIF source_name='ai_assistant_settings' AND section_name='ai' THEN keys=ARRAY['base_url','model','speed']; ELSIF source_name='contact_settings' AND section_name='notifications' THEN keys=ARRAY['recipient_email','notify_enabled','auto_reply_enabled','auto_reply_text']; ELSE RAISE EXCEPTION 'Unsupported settings section'; END IF; SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) INTO result FROM jsonb_each(row_value) WHERE key=ANY(keys); RETURN public.settings_safe_value(result); END $$;
CREATE OR REPLACE FUNCTION public.capture_settings_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sections text[]; section_name text; before_value jsonb; after_value jsonb; actor uuid; label text; BEGIN actor=auth.uid(); label=coalesce(auth.jwt()->>'email',to_jsonb(NEW)->>'updated_by',''); sections=CASE TG_TABLE_NAME WHEN 'site_settings' THEN ARRAY['general','appearance','navigation','features','contact_info','categories','customize','terms','archy'] WHEN 'ai_assistant_settings' THEN ARRAY['ai'] ELSE ARRAY['notifications'] END; FOREACH section_name IN ARRAY sections LOOP before_value=public.settings_section_value(TG_TABLE_NAME,section_name,CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END); after_value=public.settings_section_value(TG_TABLE_NAME,section_name,to_jsonb(NEW)); IF before_value IS DISTINCT FROM after_value THEN INSERT INTO public.settings_versions(section,source,actor_id,actor_label,previous_value,new_value) VALUES(section_name,TG_TABLE_NAME,actor,label,before_value,after_value); END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER phase_six_site_history AFTER INSERT OR UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.capture_settings_version();
CREATE TRIGGER phase_six_ai_history AFTER INSERT OR UPDATE ON public.ai_assistant_settings FOR EACH ROW EXECUTE FUNCTION public.capture_settings_version();
CREATE TRIGGER phase_six_contact_history AFTER INSERT OR UPDATE ON public.contact_settings FOR EACH ROW EXECUTE FUNCTION public.capture_settings_version();
CREATE OR REPLACE FUNCTION public.restore_settings_version(_version uuid,_expected jsonb,_value jsonb,_actor uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.settings_versions; current_row jsonb; current_value jsonb; restored uuid; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO h FROM public.settings_versions WHERE id=_version; IF NOT FOUND THEN RAISE EXCEPTION 'Missing version'; END IF; EXECUTE format('SELECT to_jsonb(s) FROM public.%I s WHERE id=true FOR UPDATE',h.source) INTO current_row; current_value=public.settings_section_value(h.source,h.section,current_row); IF current_value IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'settingsConflict'; END IF; IF public.settings_section_value(h.source,h.section,_value) IS DISTINCT FROM _value OR _value IS DISTINCT FROM h.previous_value THEN RAISE EXCEPTION 'Invalid restore'; END IF; IF _value='{}'::jsonb THEN RAISE EXCEPTION 'No previous value'; END IF; EXECUTE format('UPDATE public.%I SET %s, updated_at=now() WHERE id=true',h.source,(SELECT string_agg(format('%I=(jsonb_populate_record(NULL::public.%I,$1)).%I',key,h.source,key),',') FROM jsonb_object_keys(_value) AS key)) USING _value; SELECT id INTO restored FROM public.settings_versions WHERE source=h.source AND section=h.section ORDER BY created_at DESC,id DESC LIMIT 1; UPDATE public.settings_versions SET actor_id=_actor,actor_label='',restored_from=_version WHERE id=restored; INSERT INTO public.admin_activity(actor_id,actor_email,action,target) VALUES(_actor,'','settings.restore',h.section); RETURN restored; END $$;
REVOKE ALL ON FUNCTION public.restore_settings_version(uuid,jsonb,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.restore_settings_version(uuid,jsonb,jsonb,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.retention_candidates(_type text,_days integer,_limit integer) RETURNS TABLE(candidate_id text, eligible_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _days<30 OR _days>730 OR _limit<1 OR _limit>101 THEN RAISE EXCEPTION 'Invalid bounds'; END IF; IF _type='chats' THEN RETURN QUERY SELECT c.id::text,c.last_message_at FROM public.live_chats c WHERE c.last_message_at<now()-make_interval(days=>_days) AND c.status NOT IN ('waiting','active') AND NOT EXISTS(SELECT 1 FROM public.suggestion_requests r WHERE r.details->>'chatId'=c.id::text AND r.status IN ('new','in_progress')) ORDER BY c.last_message_at,c.id LIMIT _limit; ELSIF _type='visits' THEN RETURN QUERY SELECT v.visitor_key||'|'||v.day::text,v.first_seen_at FROM public.site_visits v WHERE v.first_seen_at<now()-make_interval(days=>_days) ORDER BY v.first_seen_at,v.visitor_key LIMIT _limit; ELSIF _type='telemetry' THEN RETURN QUERY SELECT t.id::text,t.created_at FROM public.application_telemetry t WHERE t.created_at<now()-make_interval(days=>_days) ORDER BY t.created_at,t.id LIMIT _limit; ELSE RAISE EXCEPTION 'Unsupported type'; END IF; END $$;
REVOKE ALL ON FUNCTION public.retention_candidates(text,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.retention_candidates(text,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.cleanup_retention_batch(_type text,_ids text[],_expected_revision integer,_actor uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days_value integer; enabled boolean; rev integer; removed integer; ids text[]; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; IF cardinality(_ids)>100 OR cardinality(_ids)<1 THEN RAISE EXCEPTION 'Invalid batch'; END IF; SELECT p.days,p.manual_enabled,p.revision INTO days_value,enabled,rev FROM public.retention_policies p WHERE p.data_type=_type FOR UPDATE; IF NOT FOUND OR NOT enabled OR rev IS DISTINCT FROM _expected_revision THEN RAISE EXCEPTION 'retentionConflict'; END IF; LOCK TABLE public.suggestion_requests IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.live_chats IN SHARE ROW EXCLUSIVE MODE; SELECT array_agg(candidate_id) INTO ids FROM public.retention_candidates(_type,days_value,100) WHERE candidate_id=ANY(_ids); IF _type='chats' THEN DELETE FROM public.live_chats WHERE id::text=ANY(ids); ELSIF _type='visits' THEN DELETE FROM public.site_visits WHERE visitor_key||'|'||day::text=ANY(ids); ELSIF _type='telemetry' THEN DELETE FROM public.application_telemetry WHERE id::text=ANY(ids); ELSE RAISE EXCEPTION 'Unsupported type'; END IF; GET DIAGNOSTICS removed=ROW_COUNT; INSERT INTO public.admin_activity(actor_id,actor_email,action,target) VALUES(_actor,'','retention.cleanup',_type||' count='||removed::text); RETURN removed; END $$;
REVOKE ALL ON FUNCTION public.cleanup_retention_batch(text,text[],integer,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_retention_batch(text,text[],integer,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.purge_expired_chats_bounded() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids text[]; removed integer; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; LOCK TABLE public.suggestion_requests IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.live_chats IN SHARE ROW EXCLUSIVE MODE; SELECT array_agg(candidate_id) INTO ids FROM public.retention_candidates('chats',90,100); DELETE FROM public.live_chats WHERE id::text=ANY(ids); GET DIAGNOSTICS removed=ROW_COUNT; RETURN removed; END $$;
REVOKE ALL ON FUNCTION public.purge_expired_chats_bounded() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purge_expired_chats_bounded() TO service_role;